/**
 * Testimonials 4 Component
 *
 * Source: @irsyad/testimonials-04 (IntentUI)
 * License: Pro Subscription
 *
 * Modifications:
 * - Integrated with PayloadCMS block system
 * - Replaced hardcoded content with dynamic props
 * - Adapted avatar handling for PayloadCMS Media uploads
 */

import { Avatar } from "@/registry/ui/avatar-intentui";
import { Container } from "@/registry/ui/container";
import type { Testimonials_4_Block } from "~/payload-types";
import type { Media } from "~/payload-types";

export default function Testimonials4(props: Testimonials_4_Block) {
	return (
		<Container className="py-6 sm:py-16">
			<h1 className="sr-only">Testimonials</h1>
			<div className="mb-8 text-center sm:mb-12">
				<h2 className="mb-4 font-semibold text-3xl md:text-4xl">{props.header}</h2>
				<p className="mx-auto max-w-2xl text-muted-fg text-xl">{props.subheader}</p>
			</div>

			<div className="columns-1 gap-2 space-y-2 sm:columns-2 lg:columns-3">
				{props.testimonials?.map((t, index) => {
					const avatarSrc =
						typeof t.avatar === "object" && t.avatar !== null
							? (t.avatar as Media).url
							: undefined;

					return (
						<div
							key={t.id || index}
							className="relative break-inside-avoid rounded-2xl border border-border bg-muted/50 p-6 duration-200 hover:shadow-md sm:p-8"
						>
							<span className="-z-10 absolute top-16 left-4 font-serif text-9xl text-muted-fg opacity-20">
								"
							</span>
							<div className="flex items-center gap-4">
								<Avatar
									src={avatarSrc}
									alt={t.name ?? ""}
									size="lg"
									initials={
										t.name
											? t.name
													.split(" ")
													.map((n) => n[0])
													.join("")
													.toUpperCase()
													.slice(0, 2)
											: undefined
									}
								/>
								<div>
									<div className="font-semibold text-fg text-sm">{t.name}</div>
									<div className="text-muted-fg text-xs">{t.role}</div>
								</div>
							</div>
							<blockquote className="mt-4 text-pretty text-base/7 text-muted-fg italic">
								"{t.quote}"
							</blockquote>
						</div>
					);
				})}
			</div>
		</Container>
	);
}

import {
	BLOCK_GROUP_TESTIMONIALS,
	BLOCK_SLUG_TESTIMONIALS_4,
} from "@/registry/default/lib/constants/blocks";
import type { Block } from "payload";
import headerField from "@/registry/default/lib/fields/header/config";
import subheaderField from "@/registry/default/lib/fields/subheader/config";
import uploadField from "@/registry/default/lib/fields/upload/config";

export const Testimonials_4_Block: Block = {
	slug: BLOCK_SLUG_TESTIMONIALS_4,
	labels: {
		singular: "Testimonials 4",
		plural: "Testimonials 4's",
	},
	admin: {
		group: BLOCK_GROUP_TESTIMONIALS,
	},
	interfaceName: "Testimonials_4_Block",
	fields: [
		{
			type: "collapsible",
			label: "Section Content",
			admin: {
				initCollapsed: false,
			},
			fields: [
				headerField({
					defaultValue: "What our customers are saying",
				}),
				subheaderField({
					defaultValue:
						"Real stories from teams who build faster, launch smoother, and never look back.",
				}),
			],
		},
		{
			type: "collapsible",
			label: "Testimonials",
			admin: {
				initCollapsed: false,
			},
			fields: [
				{
					name: "testimonials",
					label: "Testimonials",
					type: "array",
					minRows: 0,
					maxRows: 20,
					defaultValue: [
						{
							name: "Isabelle Dupont",
							role: "Product Designer at Formly",
							quote:
								"Using this product has completely transformed our design workflow. It's fast, intuitive, and reliable. We've tried dozens of tools before, but nothing felt this smooth and intentional.",
						},
						{
							name: "Lukas Hoffmann",
							role: "CTO at NovaCloud",
							quote:
								"We integrated it in less than a day and instantly saw results. Easily one of the best decisions we've made.",
						},
						{
							name: "Sophie Müller",
							role: "Marketing Lead at Brightbox",
							quote:
								"The support team is top-notch. Quick responses, friendly communication, and always willing to help. We had some edge cases, and they handled them with care and speed.",
						},
						{
							name: "Ethan Dubois",
							role: "CEO at Kapture",
							quote:
								"From performance to UI, everything just works. It's a rare thing to find something this polished. I no longer worry about stability during product launches.",
						},
						{
							name: "Charlotte Moreau",
							role: "Engineering Manager at Octave",
							quote:
								"It's so refreshing to use a tool that feels like it was made by people who understand developers.",
						},
						{
							name: "Nico Weber",
							role: "DevOps Engineer at Stackunit",
							quote:
								"Our deployment time dropped by 60% after switching. I wish we had done this earlier. The CI/CD integration is so effortless and stable.",
						},
					],
					fields: [
						{
							name: "name",
							label: "Name",
							type: "text",
							required: true,
						},
						{
							name: "role",
							label: "Role",
							type: "text",
							required: true,
						},
						uploadField({
							name: "avatar",
							label: "Avatar",
							required: false,
						}),
						{
							name: "quote",
							label: "Quote",
							type: "textarea",
							required: true,
						},
					],
				},
			],
		},
	],
};
